 if(!t||!t.closest)return;
 if(t.closest('[data-fb-open]')){e.preventDefault();open();return;}
 if(t.closest('[data-fb-close]')){e.preventDefault();close();return;}
 var cp=t.closest('[data-fb-copy]');
 if(cp){
 e.preventDefault();
 var done=function(){cp.textContent='Copied';setTimeout(function(){cp.textContent='Copy';},1800);};
 if(navigator.clipboard&&navigator.clipboard.writeText){
 navigator.clipboard.writeText(here).then(done,function(){select();});
 }else{select();}
 }
 });
 function select(){
 if(!urlBox||!window.getSelection||!document.createRange)return;
 var r=document.createRange();
 r.selectNodeContents(urlBox);
 var s=window.getSelection();
 s.removeAllRanges();
 s.addRange(r);
 }
 document.addEventListener('keydown',function(e){
 if((e.key==='Escape'||e.keyCode===27)&&!modal.hidden)close();
 });
})();
